import{c as t,U as e,h as r,l as o}from"./chunks/framework.C0iWzFTI.js";const _=JSON.parse('{"title":"分库分表","description":"","frontmatter":{},"headers":[],"relativePath":"3-数据库/MySQL/分库分表.md","filePath":"3-数据库/MySQL/分库分表.md"}'),n={name:"3-数据库/MySQL/分库分表.md"};function s(l,a,i,p,c,d){return e(),r("div",null,a[0]||(a[0]=[o('<h1 id="分库分表" tabindex="-1">分库分表 <a class="header-anchor" href="#分库分表" aria-label="Permalink to &quot;分库分表&quot;">​</a></h1><h2 id="一、简介" tabindex="-1">一、简介 <a class="header-anchor" href="#一、简介" aria-label="Permalink to &quot;一、简介&quot;">​</a></h2><p><strong>分库</strong>，将一个数据库拆分为多个数据库，主要是为了解决两个问题：</p><ul><li>并发情况下，数据库的连接问题</li><li>磁盘空间问题</li></ul><p><strong>分表</strong>，将一个表拆分为多张表，主要是为了解决单表数据量大的问题，对于单表的数据量多的问题，也可以使用分区表。</p><p>那么，如何进行拆分？这里分为两种方式：垂直拆分和水平拆分。</p><p>1）垂直拆分：按照业务含义，将表中的字段抽离出去</p><p>2）水平拆分：将表中的数据进行拆分，如订单表拆分为 订单表1 和 订单表2</p>',8)]))}const m=t(n,[["render",s]]);export{_ as __pageData,m as default};
